    @lru_cache(maxsize=None)
    def grundy(a):
        if a == 0:
            return 0

        g1 = grundy(a - 1)  # Move 1: remove one cow

        g2 = None
        if a % 2 == 0 and a // 2 > 0:
            # Move 2: replace 2x with k piles of x
            half = a // 2
            ghalf = grundy(half)
            if k % 2 == 0:
