def combinations(n, k):
    """Compute C(n, k) modulo MOD"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    return comb_mod(n, k)


def comb_mod(n, k):
    """Compute C(n, k) % MOD efficiently"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if 2 * k > n:
        k = n - k

    result = 1
    for i in range(k):
        result = (result * (n - i)) % MOD
        # Compute modular inverse for division
        result = (result * pow(i + 1, MOD - 2, MOD)) % MOD

    return result

