import math

def nCr_log(n, r):
    """Compute log of C(n, r) using lgamma for numerical stability"""
    if r < 0 or r > n:
        return -float('inf')
    if r == 0 or r == n:
        return 0.0

    r = min(r, n - r)
    return math.lgamma(n + 1) - math.lgamma(r + 1) - math.lgamma(n - r + 1)

def solution(input_str):
    n, m, k = map(int, input_str.split())

    # If m > n + k, constraint impossible: need more 10s than can be accumulated
    if m > n + k:
        return "0\n"

    # If k >= m, constraint always satisfied (enough initial 10euros)
    if k >= m:
        return "1\n"

    # Using reflection principle / ballot theorem:
    # Total arrangements: C(n+m, m)
    # Invalid arrangements (balancing happens earlier than needed): C(n+m, m-k-1)
    # This follows from the generalized ballot problem

    log_total = nCr_log(n + m, m)
    log_invalid = nCr_log(n + m, m - k - 1)

    # Probability = 1 - C(n+m, m-k-1)/C(n+m, m)
    # = 1 - exp(log_invalid - log_total)
    log_ratio = log_invalid - log_total

    # Clamp to handle numerical issues
    if log_ratio > 1e10:
        probability = 0.0
    elif log_ratio < -1e10:
        probability = 1.0
    else:
        ratio = math.exp(log_ratio)
        probability = 1.0 - ratio

    return f"{probability:.10f}\n"

