def is_lucky(num):
    """Check if a number only contains digits 4 and 7"""
    s = str(num)
    return all(c in '47' for c in s)

def generate_lucky(n):
    """Generate all lucky numbers up to n"""
    lucky = []
    q = ['4', '7']
    while q:
        s = q.pop()
        num = int(s)
        if num > n:
            continue
        lucky.append(num)
        if num * 10 + 4 <= n:
            q.append(s + '4')
        if num * 10 + 7 <= n:
            q.append(s + '7')
    return lucky

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) == 0:
        return '-1\n'

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    start_idx = 1
    for i in range(start_idx, start_idx + m):
        if i >= len(lines):
            break
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Check if any component size is already lucky
    for size in component_sizes:
        if is_lucky(size):
            return '0\n'

    # Generate lucky numbers up to n
    lucky_nums = generate_lucky(n)

    # DP: dp[s] = minimum number of components needed to sum to s
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in component_sizes:
        for s in range(n - size, -1, -1):
            if dp[s] + 1 < dp[s + size]:
                dp[s + size] = dp[s] + 1

    # Find minimum roads needed (components - 1) to form a lucky region
    ans = float('inf')
    for num in lucky_nums:
        if num <= n and 2 <= dp[num] <= len(component_sizes):
            ans = min(ans, dp[num] - 1)

    if ans == float('inf'):
        return '-1\n'

    return str(ans) + '\n'

