        total = 0
        n_arr = len(arr)
        for i in range(n_arr):
            for j in range(i+1, n_arr):
                dx = arr[i][0] - arr[j][0]
                dy = arr[i][1] - arr[j][1]
                total += dx*dx + dy*dy
        return total

    best_score = -1
    best_arr = None

    # Efficient search with retries
    for _ in range(5000):
        arr = [random.choice(points) for _ in range(n)]
        emerg = calc_score(arr)
        if emerg > best_score:
            best_score = emerg
            best_arr = arr.copy()

    # Add deterministic fallback
    boundary_points = [p for p in points if p[0]*p[0] + p[1]*p[1] == r*r]
    if boundary_points:
        arr = [boundary_points[i % len(boundary_points)] for i in range(n)]
        emerg = calc_score(arr)
        if emerg > best_score:
            best_score = emerg
            best_arr = arr

    output = [str(best_score)]
    for x, y in best_arr:
        output.append(f"{x} {y}")

    return '\n'.join(output)

