        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def diagonal_valid(i, j):
        """
        Check if convex hull diagonal from i to j is valid for a monotone polygon.
        In a triangulation, vertices are ordered, so we validate that edges going
        from i to j have consistent orientation relative to the diagonal.
        """
        if abs(i - j) <= 1:
            return True

        # Check all edges going from i toward j maintain same orientation
        di = cross_product(coords[i], coords[i+1], coords[j])

        for k in range(i + 1, j):
            if k + 1 < n or (k == n - 1 and j <= n - 1):
                di2 = cross_product(coords[i], coords[i+1], coords[j])
                if di2 * di < 0:
                    return False

        return True

    @lru_cache(maxsize=None)
    def dp(i, j):
        if j - i < 2:
            return 1

        count = 0
        for k in range(i + 1, j):
            if diagonal_valid(i, k) and diagonal_valid(k, j):
                count = (count + dp(i, k) * dp(k, j)) % MOD
        return count

    result = dp(0, n - 1)
    return f"{result}\n"

