import sys

def solution(input_str):
    """
    Solution for the Zookeeper's sheep problem (easy version with q=1).

    We need to write k non-negative integers that sum to n, maximizing the total fortune.
    Fortune is calculated based on digits in lucky positions.
    """
    lines = input_str.strip().split('\n')
    if not lines or len(lines) < 4:
        return ""

    k = int(lines[0])
    F = list(map(int, lines[1].split()))
    q = int(lines[2])

    if q == 0:
        return ""

    idx = 3
    results = []

    for _ in range(q):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        if n == 0:
            results.append("0\n")
            continue

        # Greedy approach: distribute n into k parts to maximize fortune
        # Base value for each number (trying to keep them close)
        base = n // k
        remainder = n % k

        # Create the k numbers: remainder numbers get base+1, rest get base
        numbers = [base + 1] * remainder + [base] * (k - remainder)

        # Calculate fortune for each number and sum them
        total_fortune = 0

        for num in numbers:
            if num == 0:
                continue

            pos = 0
            work_fortune = 0
            while num > 0:
                digit = num % 10
                pos += 1

                # Add fortune for this position if digit is non-zero
                if digit > 0 and pos - 1 < len(F):
                    work_fortune += digit * F[pos - 1]

                num //= 10

            total_fortune += work_fortune

        results.append(str(total_fortune) + '\n')

    return ''.join(results)


